#include <EEPROM.h>
struct Config { int version; float threshold; char name[16]; };

void setup() {
  Serial.begin(115200);
  Config c = {1, 23.5, "sensor-a"};
  EEPROM.put({{address}}, c);
  Config r;
  EEPROM.get({{address}}, r);
  Serial.print(r.version); Serial.print(' ');
  Serial.print(r.threshold); Serial.print(' ');
  Serial.println(r.name);
}

void loop() {}
